#!/usr/bin/env bun
/**
 * Regenerates TypeScript types + Pydantic models from packages/protocol/schema.
 * Deterministic: sorted keys, stable output. CI fails if generated files drift.
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');
const schemaDir = join(root, 'schema');
const tsOutDir = join(root, 'src', 'generated');
const pyOutDir = resolve(root, '../../backend/api/app/protocol_gen');

const HEADER_TS = `/* eslint-disable */
/**
 * This file was automatically generated by \`just codegen\`.
 * DO NOT MODIFY IT BY HAND. Run \`just codegen\` instead.
 */
`;

const HEADER_PY = `"""Auto-generated by \`just codegen\`. DO NOT EDIT BY HAND."""

from __future__ import annotations

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field

`;

const PY_RESERVED = new Set([
  'False',
  'None',
  'True',
  'and',
  'as',
  'assert',
  'async',
  'await',
  'break',
  'class',
  'continue',
  'def',
  'del',
  'elif',
  'else',
  'except',
  'finally',
  'for',
  'from',
  'global',
  'if',
  'import',
  'in',
  'is',
  'lambda',
  'nonlocal',
  'not',
  'or',
  'pass',
  'raise',
  'return',
  'try',
  'while',
  'with',
  'yield',
]);

function toPascal(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9]+/g, ' ')
    .split(' ')
    .filter(Boolean)
    .map((p) => p[0]!.toUpperCase() + p.slice(1))
    .join('');
}

function uniqueUnion(parts: string[]): string {
  return [...new Set(parts.filter(Boolean))].join(' | ') || 'Any';
}

function jsonSchemaTypeToPy(
  schema: Record<string, unknown>,
  defs: Record<string, unknown>,
): string {
  if (schema.$ref && typeof schema.$ref === 'string') {
    const ref = schema.$ref.split('/').pop()!;
    return toPascal(ref);
  }
  if (schema.const !== undefined) {
    const v = schema.const;
    if (typeof v === 'string') return `Literal[${JSON.stringify(v)}]`;
    if (typeof v === 'number' || typeof v === 'boolean') return `Literal[${v}]`;
  }
  if (Array.isArray(schema.enum)) {
    const parts = schema.enum.map((v) =>
      typeof v === 'string' ? JSON.stringify(v) : String(v),
    );
    return `Literal[${parts.join(', ')}]`;
  }
  if (schema.oneOf && Array.isArray(schema.oneOf)) {
    return uniqueUnion(
      (schema.oneOf as Record<string, unknown>[]).map((s) => jsonSchemaTypeToPy(s, defs)),
    );
  }
  if (schema.type === 'string') return 'str';
  if (schema.type === 'integer') return 'int';
  if (schema.type === 'number') return 'float';
  if (schema.type === 'boolean') return 'bool';
  if (schema.type === 'null') return 'None';
  if (Array.isArray(schema.type)) {
    return uniqueUnion(
      (schema.type as string[]).map((t) => jsonSchemaTypeToPy({ type: t }, defs)),
    );
  }
  if (schema.type === 'array') {
    const items = (schema.items as Record<string, unknown>) ?? {};
    return `list[${jsonSchemaTypeToPy(items, defs)}]`;
  }
  if (schema.type === 'object') {
    return 'dict[str, Any]';
  }
  return 'Any';
}

function pyFieldName(key: string): { name: string; alias?: string } {
  if (PY_RESERVED.has(key)) {
    return { name: `${key}_`, alias: key };
  }
  return { name: key };
}

function emitPydanticModels(
  title: string,
  definitions: Record<string, Record<string, unknown>>,
): string {
  const lines: string[] = [];
  lines.push(`# --- ${title} ---`);
  lines.push('');

  for (const name of Object.keys(definitions).sort()) {
    const def = definitions[name]!;
    const className = toPascal(name);
    lines.push(`class ${className}(BaseModel):`);
    lines.push(
      '    model_config = ConfigDict(extra="forbid", populate_by_name=True)',
    );
    lines.push('');

    const props = (def.properties as Record<string, Record<string, unknown>>) ?? {};
    const required = new Set((def.required as string[]) ?? []);
    const keys = Object.keys(props).sort((a, b) => {
      const ar = required.has(a) ? 0 : 1;
      const br = required.has(b) ? 0 : 1;
      if (ar !== br) return ar - br;
      return a.localeCompare(b);
    });

    if (keys.length === 0) {
      lines.push('    pass');
      lines.push('');
      continue;
    }

    for (const key of keys) {
      const prop = props[key]!;
      const { name: fieldName, alias } = pyFieldName(key);
      let ty = jsonSchemaTypeToPy(prop, definitions);
      const isRequired = required.has(key);
      if (!isRequired && !ty.split(' | ').includes('None')) {
        ty = `${ty} | None`;
      }
      // Collapse accidental duplicates like "X | None | None"
      ty = uniqueUnion(ty.split(' | ').map((s) => s.trim()));

      const fieldArgs: string[] = [];
      if (alias) fieldArgs.push(`alias=${JSON.stringify(alias)}`);
      if (typeof prop.maxLength === 'number') fieldArgs.push(`max_length=${prop.maxLength}`);
      if (typeof prop.minLength === 'number') fieldArgs.push(`min_length=${prop.minLength}`);
      if (typeof prop.minimum === 'number') fieldArgs.push(`ge=${prop.minimum}`);
      if (typeof prop.maximum === 'number') fieldArgs.push(`le=${prop.maximum}`);
      if (typeof prop.pattern === 'string') fieldArgs.push(`pattern=${JSON.stringify(prop.pattern)}`);

      if (!isRequired) {
        if (fieldArgs.length > 0) {
          lines.push(`    ${fieldName}: ${ty} = Field(${fieldArgs.join(', ')}, default=None)`);
        } else {
          lines.push(`    ${fieldName}: ${ty} = None`);
        }
      } else if (fieldArgs.length > 0) {
        lines.push(`    ${fieldName}: ${ty} = Field(${fieldArgs.join(', ')})`);
      } else {
        lines.push(`    ${fieldName}: ${ty}`);
      }
    }
    lines.push('');
  }

  return lines.join('\n');
}

async function generateTs(schemaPath: string, outName: string): Promise<string> {
  const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
  const bannerComment = HEADER_TS.trimEnd();
  const compiled = await compile(schema, schema.title ?? outName, {
    bannerComment,
    cwd: schemaDir,
    style: { singleQuote: true, semi: true, trailingComma: 'all' },
    unreachableDefinitions: true,
    unknownAny: false,
    additionalProperties: false,
  });
  return compiled.endsWith('\n') ? compiled : `${compiled}\n`;
}

async function main(): Promise<void> {
  mkdirSync(tsOutDir, { recursive: true });
  mkdirSync(pyOutDir, { recursive: true });

  const schemas = readdirSync(schemaDir)
    .filter((f) => f.endsWith('.json'))
    .sort();

  const tsIndexExports: string[] = [];
  const pyParts: string[] = [HEADER_PY];

  for (const file of schemas) {
    const schemaPath = join(schemaDir, file);
    const base = file.replace(/\.json$/, '');
    const ns = toPascal(base);
    const tsName = `${base}.ts`;
    const ts = await generateTs(schemaPath, ns);
    writeFileSync(join(tsOutDir, tsName), ts, 'utf8');
    // Namespace exports avoid colliding Ping/Pong/Kicked across ctrl + signaling.
    tsIndexExports.push(`export * as ${ns} from './${base}.js';`);

    const schema = JSON.parse(readFileSync(schemaPath, 'utf8')) as {
      title?: string;
      definitions?: Record<string, Record<string, unknown>>;
    };
    if (schema.definitions) {
      pyParts.push(emitPydanticModels(schema.title ?? base, schema.definitions));
    }
  }

  const tsIndex = `${HEADER_TS}\n${tsIndexExports.join('\n')}\n`;
  writeFileSync(join(tsOutDir, 'index.ts'), tsIndex, 'utf8');

  pyParts.push('__all__ = [name for name in globals() if not name.startswith("_")]\n');
  writeFileSync(join(pyOutDir, '__init__.py'), pyParts.join('\n'), 'utf8');
  writeFileSync(join(pyOutDir, 'models.py'), 'from . import *  # noqa: F403\n', 'utf8');

  const relTs = relative(process.cwd(), tsOutDir);
  const relPy = relative(process.cwd(), pyOutDir);
  console.log(`codegen ok → ${relTs} + ${relPy} (${schemas.length} schemas)`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
